import numpy as np,csv,collections
py=np.load('iter_1/candidate_1/scratch/py_none_10.npy');rows=list(csv.DictReader(open('responses.csv')))
y=np.array([int(float(r['rating'])) for r in rows])
S=collections.defaultdict(list)
for i,r in enumerate(rows): S[r['number_set']].append(i)
for m in [3,4,6,7,8,9,11,12]:
  for s,ix in S.items():
    e=[int(x) for x in s.split(',')]
    if all(x%m==0 for x in e) and len(e)>1:
      ix=np.array(ix);T=np.array([int(rows[i]['target']) for i in ix]);mm=(T%m==0)&~np.isin(T,e)
      if mm.sum() and (~mm).sum(): print(m,s,'mult obs %.2f pred %.2f | non obs %.2f pred %.2f'%(y[ix][mm].mean(),py[ix][mm].mean(),y[ix][~mm].mean(),py[ix][~mm].mean()), mm.sum())
"

